	/**
	 * Works like {@link #waitForValue(Supplier)}, except this caches {@link NoSuchElementException}
	 * and tries again.
	 *
	 * @param <T> the type of object to wait for
	 * @param supplier the supplier of the object
	 * @return the object
	 */protected static T waitForElement<T>(Supplier<T> supplier) {
		return waitForValue(() => {
			try {
				return supplier.get();
			}
			catch (NoSuchElementException e) {
				return null;
			}
		});
	}

	protected static void waitForNoElement(Supplier<object> supplier) {
		waitForValue(() => {
			try {
				supplier.get();
				return null;
			}
			catch (NoSuchElementException e) {
				return new object();
			}
		});
	}

