	/* @Before */
	public void setUp()
    {
		env = new TestEnv();
		tool = env.getTool();

		targetService = addPlugin(tool, typeof(DebuggerTargetServicePlugin));

		addPlugin(tool, typeof(DebuggerTraceManagerServicePlugin));
		traceManager = tool.getService(typeof(DebuggerTraceManagerService));

		programManager = tool.getService(typeof(ProgramManager));

		env.showTool();
	}

	/* @After */
	public void tearDown() {
		try {
			waitForTasks();
			runSwing(() => {
				if (traceManager == null) {
					return;
				}
				traceManager.setSaveTracesByDefault(false);
			});

			if (tb != null) {
				if (traceManager != null && traceManager.getOpenTraces().contains(tb.trace)) {
					traceManager.closeTraceNoConfirm(tb.trace);
				}
				tb.close();
			}

			programManager.closeAllPrograms(true);
			if (program != null) {
				program.release(this);
			}

			waitForTasks();
		}
		finally {
			env.dispose();
		}
	}

	protected void intoProject(DomainObject obj) {
		waitForDomainObject(obj);
		DomainFolder rootFolder = tool.getProject().getProjectData().getRootFolder();
		waitForCondition(() => {
			try {
				rootFolder.createFile(obj.getName(), obj, monitor);
				return true;
			}
			catch (Exception e) when (e is InvalidNameException or CancelledException) {
				throw new AssertionError(e);
			}
			catch (IOException e) {
				// Usually "object is busy". Try again.
				return false;
			}
		});
	}

